SELECT s.session_id,s.user_id,t.turn_no, r.shelf_position,r.video_id,i.impression_id, SUM(vs.watched_ms) watched_ms, MAX(vs.reached_end) reached_end FROM Recommendation r CROSS JOIN AgentTurn t ON t.turn_id=r.turn_id CROSS JOIN AgentSession s ON s.session_id=t.session_id CROSS JOIN Impression i ON i.recommendation_id=r.recommendation_id AND i.user_id=s.user_id CROSS JOIN ViewSegment vs ON vs.impression_id=i.impression_id GROUP BY s.session_id,s.user_id,t.turn_no, r.shelf_position,r.video_id,i.impression_id HAVING MAX(vs.reached_end)=1 ORDER BY s.session_id,t.turn_no,r.shelf_position LIMIT 20;
